import{_ as l,C as c,o as n,c as g,j as d,a as e,E as o,a5 as r}from"./chunks/framework.Dep_XxFZ.js";const S=JSON.parse('{"title":"浮动面板","description":"","frontmatter":{},"headers":[],"relativePath":"components/floating-panel.md","filePath":"components/floating-panel.md","lastUpdated":1787365442000}'),s={name:"components/floating-panel.md"},h={id:"浮动面板",tabindex:"-1"};function p(b,t,f,u,x,P){const i=c("Badge"),a=c("XhDemo");return n(),g("div",null,[d("h1",h,[t[0]||(t[0]=e("浮动面板 ",-1)),o(i,{type:"info",text:"floating-panel"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#浮动面板","aria-label":'Permalink to "浮动面板 <Badge type="info" text="floating-panel" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一块浮在页面上、能搬走、能改大小、能收拢与铺满的非模态面板。页面照常可读可点，面板停在用户放它的地方。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>长时间挂着的辅助界面：调试面板、图层属性、正在进行的通话、播放器。</li><li>用户需要一边看页面一边改东西，弹窗那种&quot;必须先处理完&quot;的语气不合适。</li><li>位置和大小要由用户自己定，并且值得记下来（<code>onPositionChange</code> / <code>onSizeChange</code> / <code>onStageChange</code> 就是为此留的）。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>必须先处理完才能继续：用<a href="./dialog">对话框</a>，它会陷住焦点、锁住背景。</li><li>从边上滑出的一整块面板：用<a href="./drawer">抽屉</a>。</li><li>挂在某个元素旁边、点别处就收：用<a href="./popover">气泡卡片</a>。</li><li>只是把一块区域分成可拖的几片：用<a href="./splitter">分栏</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>三种形态：常规、收拢（只留标题栏）、铺满（占满视口），由 <code>stage</code> 一个值表达，可受控。</li><li>位置与尺寸各自成对（<code>position</code> / <code>defaultPosition</code>、<code>size</code> / <code>defaultSize</code>），两态齐全。</li><li>八个改尺把手在节点上自报守的是哪条边，西边与北边的把手会同时改位置。</li><li>键盘全程可达：拖拽把手上方向键平移、Shift 快移、Enter / Space 送回初始落点；改尺把手上方向键推边；Esc 关闭。</li><li><code>minSize</code> / <code>maxSize</code> 在每一处入口都生效——拖、推、<code>setSize</code> 走的是同一个夹取函数。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>点触发器打开面板：标题栏那条把手可以拖，右下角可以改大小，Esc 关闭</p>',10)),o(a,{src:"floating-panel/01-basic"}),t[4]||(t[4]=d("h3",{id:"三种形态",tabindex:"-1"},[e("三种形态 "),d("a",{class:"header-anchor",href:"#三种形态","aria-label":'Permalink to "三种形态"'},"​")],-1)),t[5]||(t[5]=d("p",null,"收拢只留标题栏、铺满占满视口；按着的那个钮再按一次回到常规",-1)),o(a,{src:"floating-panel/02-stage"}),t[6]||(t[6]=d("h3",{id:"八个改尺把手",tabindex:"-1"},[e("八个改尺把手 "),d("a",{class:"header-anchor",href:"#八个改尺把手","aria-label":'Permalink to "八个改尺把手"'},"​")],-1)),t[7]||(t[7]=d("p",null,"四条边加四个角；min-size 与 max-size 在拖、推、setSize 三处同时生效",-1)),o(a,{src:"floating-panel/03-resize"}),t[8]||(t[8]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[9]||(t[9]=d("p",null,"open 与 position 都交给外面握着：面板只报意图，值写回来才动",-1)),o(a,{src:"floating-panel/04-controlled"}),t[10]||(t[10]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[11]||(t[11]=d("p",null,"搬不动、改不了尺寸、切不了形态；关闭与开合照常，面板不会被锁死在屏幕上",-1)),o(a,{src:"floating-panel/05-disabled"}),t[12]||(t[12]=d("h3",{id:"文案本地化",tabindex:"-1"},[e("文案本地化 "),d("a",{class:"header-anchor",href:"#文案本地化","aria-label":'Permalink to "文案本地化"'},"​")],-1)),t[13]||(t[13]=d("p",null,"把手与几个按钮只有图标，可及名一律走 translations",-1)),o(a,{src:"floating-panel/06-translations"}),t[14]||(t[14]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-floating-panel&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhFloatingPanelBody</code> <code>XhFloatingPanelCloseTrigger</code> <code>XhFloatingPanelContent</code> <code>XhFloatingPanelDragTrigger</code> <code>XhFloatingPanelHeader</code> <code>XhFloatingPanelPositioner</code> <code>XhFloatingPanelResizeTrigger</code> <code>XhFloatingPanelRoot</code> <code>XhFloatingPanelStageTrigger</code> <code>XhFloatingPanelTitle</code> <code>XhFloatingPanelTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useFloatingPanel</code></td></tr><tr><td>状态机</td><td><code>floatingPanelMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/floating-panel.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;floating-panel&quot;</code>：<code>root</code> · <code>trigger</code> · <strong><code>positioner</code></strong> · <strong><code>content</code></strong> · <code>header</code> · <code>title</code> · <code>drag-trigger</code> · <code>resize-trigger</code> · <code>stage-trigger</code> · <code>close-trigger</code> · <code>body</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td>展开态。给定即受控：内部不再自改，只发 onOpenChange。</td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>position</code></td><td><code>FloatingPanelPosition</code></td><td></td><td>面板左上角坐标（px，相对视口）。给定即受控。</td></tr><tr><td><code>defaultPosition</code></td><td><code>FloatingPanelPosition</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>FloatingPanelSize</code></td><td></td><td>面板尺寸（px）。给定即受控。</td></tr><tr><td><code>defaultSize</code></td><td><code>FloatingPanelSize</code></td><td></td><td></td></tr><tr><td><code>minSize</code></td><td><code>FloatingPanelSize</code></td><td></td><td>尺寸下限，默认 160×120。</td></tr><tr><td><code>maxSize</code></td><td><code>FloatingPanelSize</code></td><td></td><td>尺寸上限，不给即不封顶。与 minSize 冲突时以 minSize 为准。</td></tr><tr><td><code>stage</code></td><td><code>FloatingPanelStage</code></td><td></td><td>形态。给定即受控。</td></tr><tr><td><code>defaultStage</code></td><td><code>FloatingPanelStage</code></td><td></td><td></td></tr><tr><td><code>draggable</code></td><td><code>boolean</code></td><td></td><td>允不允许搬动面板，默认 true；铺满形态下恒不可搬。</td></tr><tr><td><code>resizable</code></td><td><code>boolean</code></td><td></td><td>允不允许改尺寸，默认 true；只有常规形态下才改得动。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：搬不动、改不了尺寸、切不了形态；开合与关闭不受影响。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;FloatingPanelTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: FloatingPanelOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr><tr><td><code>onPositionChange</code></td><td><code>(details: FloatingPanelPositionChangeDetails) =&gt; void</code></td><td></td><td>位置变化意图回调；拖动过程中会连续发很多次。</td></tr><tr><td><code>onSizeChange</code></td><td><code>(details: FloatingPanelSizeChangeDetails) =&gt; void</code></td><td></td><td>尺寸变化意图回调；改尺过程中会连续发很多次。</td></tr><tr><td><code>onStageChange</code></td><td><code>(details: FloatingPanelStageChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>FloatingPanelOpenChangeDetails</code></td><td>展开态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>position-change</code></td><td><code>FloatingPanelPositionChangeDetails</code></td><td>落点变化（拖动途中会连发）；detail 为 <code>{ position: { x, y } }</code></td></tr><tr><td><code>size-change</code></td><td><code>FloatingPanelSizeChangeDetails</code></td><td>尺寸变化（改尺途中会连发）；detail 为 <code>{ size: { width, height } }</code></td></tr><tr><td><code>stage-change</code></td><td><code>FloatingPanelStageChangeDetails</code></td><td>形态变化；detail 为 <code>{ stage: &#39;default&#39; | &#39;minimized&#39; | &#39;maximized&#39; }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhFloatingPanelRoot</code></td><td><code>default</code></td><td><code>FloatingPanelRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>stage-trigger</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>closed</code> · <code>open</code> · <code>open.dragging</code> · <code>open.idle</code> · <code>open.resizing</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>TOGGLE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code> · <code>POSITION.SET</code> · <code>POSITION.NUDGE</code> · <code>SIZE.SET</code> · <code>SIZE.NUDGE</code> · <code>STAGE.SET</code> · <code>DRAG.START</code> · <code>RESIZE.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code></p><p><strong>判据</strong>：<code>canDrag</code> · <code>canInteract</code> · <code>canResize</code> · <code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useFloatingPanel</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>stage</code></td><td><code>FloatingPanelStage</code></td><td></td></tr><tr><td><code>position</code></td><td><code>FloatingPanelPosition</code></td><td></td></tr><tr><td><code>size</code></td><td><code>FloatingPanelSize</code></td><td></td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>正在被指针搬动。</td></tr><tr><td><code>resizing</code></td><td><code>boolean</code></td><td>正在被指针改尺。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>canDrag</code></td><td><code>boolean</code></td><td>眼下搬不搬得动：作者允许、未禁用、且不是铺满形态。</td></tr><tr><td><code>canResize</code></td><td><code>boolean</code></td><td>眼下改不改得了尺寸：作者允许、未禁用、且是常规形态。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>setPosition</code></td><td><code>(next: FloatingPanelPosition) =&gt; void</code></td><td></td></tr><tr><td><code>setSize</code></td><td><code>(next: FloatingPanelSize) =&gt; void</code></td><td>尺寸会被夹进 minSize / maxSize 之后才落地。</td></tr><tr><td><code>setStage</code></td><td><code>(next: FloatingPanelStage) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDragTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getResizeTriggerProps</code></td><td><code>(props: FloatingPanelResizeTriggerProps) =&gt; T[&#39;element&#39;]</code></td><td>把手是 role=separator 的元素而不是按钮：方向键推边，激活键在这里没有语义。</td></tr><tr><td><code>getStageTriggerProps</code></td><td><code>(props: FloatingPanelStageTriggerProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBodyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>focus in content, 面板展开</td><td>关闭面板；面板不是模态的，焦点在页面别处时这一键不归它管</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>ArrowLeft</code> / <code>ArrowRight</code></td><td>focus on drag-trigger, 未禁用、draggable 开启且不是铺满形态</td><td>把整块面板往该方向平移 10px</td></tr><tr><td><code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code> / <code>Shift+ArrowLeft</code> / <code>Shift+ArrowRight</code></td><td>focus on drag-trigger, 未禁用、draggable 开启且不是铺满形态</td><td>同上，一下走 50px</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on drag-trigger, 未禁用、draggable 开启且不是铺满形态</td><td>把面板送回初始落点（defaultPosition，没给就是 24,24）；面板被拖出视口后靠这一键收回来</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>ArrowLeft</code> / <code>ArrowRight</code></td><td>focus on resize-trigger, 未禁用、resizable 开启且是常规形态</td><td>把这个把手守的那条边往该方向推 10px；推不动的那根轴上不拦键（上下把手放行左右键）</td></tr><tr><td><code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code> / <code>Shift+ArrowLeft</code> / <code>Shift+ArrowRight</code></td><td>focus on resize-trigger, 未禁用、resizable 开启且是常规形态</td><td>同上，一下推 50px</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>drag-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>drag-trigger</code></td><td><code>aria-label</code></td><td>label.dragTrigger</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-label</code></td><td>label.resizeTrigger(item.edge)</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-orientation</code></td><td>&#39;vertical&#39; | &#39;horizontal&#39;</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuemax</code></td><td>String(Math.round(valueMax)) | undefined</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuemin</code></td><td>String(Math.round(horizontal ? minSize.width : minSiz…</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuenow</code></td><td>String(Math.round(horizontal ? size.width : size.heig…</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuetext</code></td><td>label.resizeValueText(size)</td></tr><tr><td><code>resize-trigger</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr><tr><td><code>stage-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>stage-trigger</code></td><td><code>aria-label</code></td><td>label.stageTrigger(item.stage)</td></tr><tr><td><code>stage-trigger</code></td><td><code>aria-pressed</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>label.close</td></tr></tbody></table><ul><li>面板是 <code>role=&quot;dialog&quot;</code> 且 <code>aria-modal=&quot;false&quot;</code>：它不夺走焦点，页面其余部分照常可达。</li><li>标题部件的 id 恒被 <code>aria-labelledby</code> 指向，因此<strong>面板一定要写标题</strong>，否则读屏只能念出&quot;对话框&quot;。</li><li>拖拽把手、八个改尺把手、三个形态按钮、关闭按钮都只有图标，可及名一律走 <code>translations</code>。</li><li>八个改尺把手是 <code>role=&quot;separator&quot;</code>：<code>aria-valuenow</code> 报它推的那根轴的像素值（左右两侧与四角报宽度、上下两条报高度），<code>aria-valuetext</code> 把宽高一并念出来。不给 <code>maxSize</code> 时 <code>aria-valuemax</code> 缺席，播报以 <code>aria-valuetext</code> 为准。</li><li>拖拽把手是原生按钮，它的激活键（Enter / Space）有实义：把面板送回初始落点。按钮不响应自己的激活键是反模式。</li><li>把手在推不动时用 <code>aria-disabled</code> 而不是原生 <code>disabled</code>：后者会把它逐出 Tab 序列，键盘用户连&quot;这里能搬&quot;都读不到。改尺把手同理恒带 <code>tabindex=&quot;0&quot;</code>。</li><li>收拢时正文带上 <code>hidden</code>，其中的可聚焦元素一并退出 Tab 序列——只压高度的话读屏与 Tab 照样进得去。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/floating-panel.css</code> 按部件选择：<code>[data-scope=&quot;floating-panel&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-stage</code></td><td>context.get(&#39;stage&#39;)</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>header</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>header</code></td><td><code>data-stage</code></td><td>context.get(&#39;stage&#39;)</td></tr><tr><td><code>drag-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>drag-trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>resize-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>resize-trigger</code></td><td><code>data-edge</code></td><td>item.edge</td></tr><tr><td><code>resize-trigger</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>stage-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>stage-trigger</code></td><td><code>data-state</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr><tr><td><code>stage-trigger</code></td><td><code>data-target-stage</code></td><td>item.stage</td></tr><tr><td><code>body</code></td><td><code>data-stage</code></td><td>context.get(&#39;stage&#39;)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-floating-panel-action-bg-active</code> · <code>--xh-floating-panel-action-bg-hover</code> · <code>--xh-floating-panel-action-fg</code> · <code>--xh-floating-panel-action-fg-active</code> · <code>--xh-floating-panel-action-fg-hover</code> · <code>--xh-floating-panel-action-radius</code> · <code>--xh-floating-panel-action-size</code> · <code>--xh-floating-panel-bg</code> · <code>--xh-floating-panel-body-px</code> · <code>--xh-floating-panel-body-py</code> · <code>--xh-floating-panel-border</code> · <code>--xh-floating-panel-close-radius</code> · <code>--xh-floating-panel-close-size</code> · <code>--xh-floating-panel-corner-size</code> · <code>--xh-floating-panel-fg</code> · <code>--xh-floating-panel-handle-size</code> · <code>--xh-floating-panel-header-bg</code> · <code>--xh-floating-panel-header-border</code> · <code>--xh-floating-panel-header-gap</code> · <code>--xh-floating-panel-header-px</code> · <code>--xh-floating-panel-header-py</code> · <code>--xh-floating-panel-icon-size</code> · <code>--xh-floating-panel-layer</code> · <code>--xh-floating-panel-radius</code> · <code>--xh-floating-panel-shadow</code> · <code>--xh-floating-panel-title-fg</code> · <code>--xh-floating-panel-title-font-size</code> · <code>--xh-floating-panel-title-font-weight</code> · <code>--xh-floating-panel-trigger-bg</code> · <code>--xh-floating-panel-trigger-border</code> · <code>--xh-floating-panel-trigger-fg</code> · <code>--xh-floating-panel-trigger-h</code> · <code>--xh-floating-panel-trigger-px</code> · <code>--xh-floating-panel-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>面板的坐标、八个把手的方位、方向键推动的方向<strong>都是屏幕方位，不随 <code>dir</code> 翻转</strong>。<code>w</code> 把手在 RTL 下仍长在物理左侧，按右方向键面板仍往屏幕右边走——指针位移本来就是屏幕坐标，跟着 <code>dir</code> 翻会让手上的方向与面板的动向对不上。</li><li>因此皮肤里改尺把手那一段刻意写物理的 <code>inset</code> / <code>width</code> / <code>height</code>，连接层写的也是 <code>left</code> / <code>top</code>。<strong>不要</strong>把它们改成 <code>inset-inline-*</code>：把手会跑到对面，手往右拖却从左边收。</li><li>面板内的正文照常跟随文档方向：标题栏的排布、正文的书写方向都由外面的 <code>dir</code> 决定，本组件一个字都不管。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>标题栏里放<a href="./button-group">按钮组</a>承载三个形态按钮与关闭按钮。</li><li>正文放<a href="./scroll-area">滚动区域</a>：面板被改小后正文自己滚，而不是把面板撑破。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>位置与尺寸值得存下来：拖动途中回调每帧都发，落存储前先节流。</li><li>面板被搬到视口外之后，<strong>再点触发按钮不会把它挪回来</strong>——重新展开只是在同一个坐标上再展开一次。真正能收回来的只有两条：焦点落在拖拽把手上按 Enter / Space（送回初始落点），或者受控接管 <code>position</code>、在打开时写回一个视口内的坐标。产品线要&quot;永远拖不出屏幕&quot;就得走后一条。</li><li>面板关闭或被搬走后，焦点会掉回 <code>&lt;body&gt;</code>：本组件不接管焦点归还，作者应在关闭后把焦点送回触发按钮。</li><li>同屏挂多块面板时给它们不同的初始落点，否则会叠成一摞、只有最上面那块点得到。</li><li>位置不做视口夹取：组件一次也不量视口，<code>onPositionChange</code> 里发出来的坐标就是指针算出来的原值。</li><li>面板的落位是视口坐标（<code>position: fixed</code> + <code>left</code> / <code>top</code>）。Vue 侧定位层会被搬到统一的浮层落点，祖先怎么写都不影响；<strong>Web Components 侧搬不动</strong>（角色节点作者写在哪就在哪），把 <code>&lt;xh-floating-panel&gt;</code> 放进带 <code>transform</code> / <code>filter</code> / <code>backdrop-filter</code> / <code>contain: paint</code> 的容器里，那个祖先会抢走包含块，面板会落到错误的位置——展开时元素会投一条 <code>overlay.stacking-trap</code> 诊断。</li><li>Web Components 侧&quot;能不能搬&quot;这个开关的属性名是 <code>panel-draggable</code> 而不是 <code>draggable</code>：<code>draggable</code> 是 HTML 全局属性，占用它会把宿主元素变成原生拖放源，<code>dragstart</code> 一起浏览器就派 <code>pointercancel</code>，指针拖动当场中止。property 名同样是 <code>panelDraggable</code>；Vue 侧不受影响，仍是 <code>draggable</code>。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它当对话框用来确认删除：非模态面板允许用户绕开，重要的确认必须挡住去路。</li><li>一屏挂五六块浮动面板：它们互相遮挡，用户先要整理桌面才能干活。</li><li>把面板做成不可关闭也不可收拢：浮层挡住的正是用户要看的内容。</li></ul>',50))])}const z=l(s,[["render",p]]);export{S as __pageData,z as default};
